//! TypeScript generated from Rust: the bridge's protocol types, and a
//! plugin's parameter map from its declarations.
//!
//! The page imports these declarations instead of writing its own. A message
//! that changes shape in Rust, or a parameter that is renamed, is therefore a
//! compile error in the page. Generated files are committed, `cargo xtask gen`
//! rewrites them all, and each has a drift gate that fails when it is stale
//! (`tests/typescript_drift.rs` for the protocol).

use std::fmt::Write as _;

use seam_params::{Kind, ParamSet};
use ts_rs::{Config, TS};

use crate::protocol::{CallResult, NativeMessage, PROTOCOL_VERSION, PageMessage, ParamState};

/// The protocol's message types as TypeScript declarations, in a fixed order.
fn declarations() -> [String; 4] {
    let cfg = Config::new();
    [
        PageMessage::decl(&cfg),
        NativeMessage::decl(&cfg),
        ParamState::decl(&cfg),
        CallResult::decl(&cfg),
    ]
}

/// The protocol module the page imports: every message type, and the
/// protocol version as a constant.
///
/// # Examples
///
/// ```
/// let module = seam_bridge::typescript::protocol();
/// assert!(module.contains("export const PROTOCOL_VERSION"));
/// assert!(module.contains("export type PageMessage"));
/// ```
pub fn protocol() -> String {
    let mut out = String::from(
        "// Generated by seam-bridge from crates/bridge/src/protocol.rs. Do not edit;\n\
         // regenerate with `cargo xtask gen`.\n\n",
    );
    let _ = writeln!(out, "export const PROTOCOL_VERSION = {PROTOCOL_VERSION};");
    for decl in declarations() {
        out.push_str("\nexport ");
        out.push_str(&decl);
        out.push('\n');
    }
    out
}

/// A fingerprint of the message shapes, in sixteen hex digits.
///
/// The value is a 64-bit FNV-1a hash of the generated declarations without
/// comments or whitespace, which changes when a field or a variant is added,
/// removed, renamed or retyped, and not when a doc comment changes.
///
/// `tests/protocol_version.rs` compares it with the hash committed next to
/// [`PROTOCOL_VERSION`], so a changed shape cannot ship under the same version.
///
/// # Examples
///
/// ```
/// let hash = seam_bridge::typescript::shape_hash();
/// assert_eq!(hash.len(), 16);
/// assert!(hash.bytes().all(|byte| byte.is_ascii_hexdigit()));
/// ```
pub fn shape_hash() -> String {
    hash_of(&declarations())
}

/// The fingerprint of `declarations`.
fn hash_of(declarations: &[String]) -> String {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in declarations.iter().flat_map(|decl| code_only(decl)) {
        hash = (hash ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3);
    }
    format!("{hash:016x}")
}

/// `decl`'s bytes without block comments and whitespace.
fn code_only(decl: &str) -> Vec<u8> {
    let mut code = String::with_capacity(decl.len());
    let mut rest = decl;
    while let Some((before, comment)) = rest.split_once("/*") {
        code.push_str(before);
        rest = comment.split_once("*/").map_or("", |(_, after)| after);
    }
    code.push_str(rest);
    code.bytes()
        .filter(|byte| !byte.is_ascii_whitespace())
        .collect()
}

/// A plugin's parameter map, the page's `Params` for `createHooks`: every
/// parameter keyed by its stable key, in declaration order, with what the
/// page may show without asking. Ranges, skew and snapping stay in Rust.
///
/// `source` names where the declarations live, for the file's header.
///
/// # Examples
///
/// ```
/// use seam_bridge::typescript::param_map;
/// use seam_params::{Kind, ParamDecl, ParamSetBuilder};
///
/// # fn main() -> Result<(), seam_params::DeclError> {
/// let mut builder = ParamSetBuilder::new();
/// builder.add(ParamDecl::new("gain", "Gain", Kind::continuous(-24.0, 24.0, 0.1, None), 0.0)
///     .with_unit("dB"))?;
/// let set = builder.build();
///
/// let module = param_map(&set, "examples/eq/src/params.rs");
/// assert!(module.contains("export const PARAMS"));
/// assert!(module.contains("\"gain\": {"));
/// # Ok(())
/// # }
/// ```
pub fn param_map(set: &ParamSet, source: &str) -> String {
    let mut out = format!(
        "// Generated by seam-bridge from the parameter declarations in {source}.\n\
         // Do not edit; regenerate with `cargo xtask gen`.\n\n\
         /** Every parameter, keyed by its stable key, in declaration order, the\n    \
         order hosts list it in. Hosts know it by a hash of its key. */\n\
         export const PARAMS = {{\n"
    );
    for id in set.ids() {
        let decl = set.decl(id);
        let kind = match decl.kind {
            Kind::Continuous(_) => "continuous",
            Kind::Bool => "bool",
            Kind::Choice(_) => "choice",
        };
        let _ = writeln!(out, "  {}: {{", string(decl.key));
        let _ = writeln!(out, "    index: {},", id.index());
        let _ = writeln!(out, "    name: {},", string(decl.name));
        let _ = writeln!(out, "    unit: {},", string(decl.unit));
        let _ = writeln!(out, "    group: {},", string(decl.group));
        let _ = writeln!(out, "    kind: {},", string(kind));
        if let Kind::Choice(labels) = decl.kind {
            let labels: Vec<String> = labels.iter().map(|label| string(label)).collect();
            let _ = writeln!(out, "    labels: [{}],", labels.join(", "));
        }
        let _ = writeln!(out, "    bypass: {},", decl.bypass);
        out.push_str("  },\n");
    }
    out.push_str(
        "} as const;\n\n\
         /** The page's parameter map, for `createHooks<Params, Events, Commands>`. */\n\
         export type Params = typeof PARAMS;\n",
    );
    out
}

/// A TypeScript string literal: JSON's escaping is valid TypeScript.
fn string(text: &str) -> String {
    serde_json::to_string(text).expect("a string always serialises")
}

#[cfg(test)]
mod tests {
    use super::{code_only, declarations, hash_of, shape_hash};

    #[test]
    fn comments_and_whitespace_do_not_reach_the_fingerprint() {
        let plain = code_only("type A = { x: number, y: string };");
        let commented = code_only("type A = {\n /**\n * the x\n */\n x: number,\n y: string };");
        assert_eq!(plain, commented);
        assert_ne!(plain, code_only("type A = { x: number, y: number };"));
    }

    fn hash(decl: &str) -> String {
        hash_of(&[decl.to_owned()])
    }

    #[test]
    fn the_hash_is_fnv_1a_of_the_code() {
        // FNV-1a of "a" and of "ab", from the algorithm's published vectors.
        assert_eq!(hash("a"), "af63dc4c8601ec8c");
        assert_eq!(hash(" a /* x */ b "), "089c4407b545986a");
    }

    #[test]
    fn the_hash_moves_when_the_shape_moves() {
        let base = hash("type A = { x: number, y: string };");
        assert_ne!(
            base,
            hash("type A = { x: number, y: number };"),
            "a retyped field"
        );
        assert_ne!(
            base,
            hash("type A = { x: number, z: string };"),
            "a renamed field"
        );
        assert_ne!(base, hash("type A = { x: number };"), "a removed field");
        assert_ne!(
            base,
            hash("type A = { x: number, y: string, z: string };"),
            "an added field"
        );
        assert_ne!(
            base,
            hash("type A = { x: number, y?: string };"),
            "a field that became optional"
        );
        assert_eq!(
            base,
            hash(
                "type A = {
 /** note */ x: number,
 y: string };"
            )
        );
    }

    #[test]
    fn the_hash_covers_every_declaration_in_order() {
        let (first, second) = ("type A = 1;".to_owned(), "type B = 2;".to_owned());
        assert_ne!(
            hash_of(&[first.clone(), second.clone()]),
            hash_of(&[second.clone(), first.clone()])
        );
        assert_ne!(hash_of(&[first.clone(), second]), hash_of(&[first]));
    }

    #[test]
    fn the_shape_hash_is_the_hash_of_the_generated_declarations() {
        assert_eq!(shape_hash(), hash_of(&declarations()));
    }
}
